import { useRef, useEffect, useState } from "react";
import API from "../services/api";

const CameraRecorder = ({ incidentId }) => {

  const videoRef = useRef(null);
  const mediaRecorderRef = useRef(null);
  const streamRef = useRef(null);

  const [recordingStatus, setRecordingStatus] = useState("Idle");

  const startCameraAndRecord = async () => {
    try {
      const mediaStream = await navigator.mediaDevices.getUserMedia({
        video: true,
        audio: true
      });

      streamRef.current = mediaStream;
      videoRef.current.srcObject = mediaStream;
      
      const recorder = new MediaRecorder(mediaStream);
      let chunks = [];
      recorder.ondataavailable = (event) => chunks.push(event.data);

      recorder.onstop = async () => {
        try {
          const blob = new Blob(chunks, { type: "video/webm" });
          const formData = new FormData();
          formData.append("file", blob, "evidence.webm");
          formData.append("incidentId", incidentId);
          formData.append("mediaType", "video");

          await API.post("/evidence/upload", formData);
          console.log("Evidence uploaded");
        } catch (error) {
          console.error("Upload error:", error);
        }
      };

      recorder.start();
      mediaRecorderRef.current = recorder;
      setRecordingStatus("Recording");
    } catch (error) {
      console.error("Camera error:", error);
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current) mediaRecorderRef.current.stop();
    if (streamRef.current) streamRef.current.getTracks().forEach(track => track.stop());
    setRecordingStatus("Stopped");
  };

  useEffect(() => {
    if (incidentId) {
      startCameraAndRecord();
    } else {
      stopRecording();
    }
  }, [incidentId]);

  return (

    <div>

      <h2>Emergency Recording</h2>

      <video
        ref={videoRef}
        autoPlay
        width="400"
      />

    </div>

  );

};

export default CameraRecorder;

import { useEffect, useState } from "react";

const EmergencyMap = ({ location }) => {
  if (!location) return null;

  const mapUrl = `https://www.google.com/maps?q=${location.lat},${location.lng}&z=15&output=embed`;

  return (
    <div>
      <h2>Emergency Location</h2>
      <iframe
        title="map"
        width="600"
        height="400"
        style={{ border: 0 }}
        loading="lazy"
        allowFullScreen
        src={mapUrl}
      />
    </div>
  );
};

export default EmergencyMap;
